using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct EventId : IEquatable<EventId>, IComparable<EventId>
    {
        public Guid Value { get; }

        public EventId(Guid value)
        {
            Value = value;
        }

        public static EventId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static EventId NewRandom() => new EventId(Guid.NewGuid());

        public static EventId Parse(string text) => new EventId(Guid.Parse(text));

        public static bool TryParse(string text, out EventId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new EventId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(EventId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is EventId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(EventId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(EventId left, EventId right) => left.Equals(right);

        public static bool operator !=(EventId left, EventId right) => !left.Equals(right);
    }
}
